private IReadOnlyList<GameProfile> LoadForMutation()
{
    using var __mhwTrace = MasterDebugLog.BeginMethod();
    if(!File.Exists(registryPath))return Array.Empty<GameProfile>();
    try
    {
        var parsed=JsonSerializer.Deserialize<GameProfile[]>(File.ReadAllText(registryPath),JsonOptions)
            ?? throw new InvalidDataException("The existing game registry does not contain a valid profile list.");
        if(parsed.Any(x=>!IsUsable(x)))
            throw new InvalidDataException("The existing game registry contains an invalid game profile and cannot be rewritten safely.");
        var duplicate=parsed.GroupBy(x=>x.Id,StringComparer.OrdinalIgnoreCase).FirstOrDefault(x=>x.Count()>1);
        if(duplicate is not null)
            throw new InvalidDataException($"The existing game registry contains duplicate profile id '{duplicate.Key}' and cannot be rewritten safely.");
        return parsed.OrderBy(x=>x.DisplayName,StringComparer.OrdinalIgnoreCase).ToArray();
    }
    catch(Exception ex) when(ex is IOException or UnauthorizedAccessException or JsonException)
    {
        MasterDebugLog.Write("GAME-REGISTRY","Could not read the existing game registry for mutation; leaving it untouched.",ex);
        throw new InvalidDataException("The existing game registry could not be read safely and was left untouched.",ex);
    }
}

public void Upsert(GameProfile profile)
{
    if(!IsUsable(profile))throw new ArgumentException("Game profile is invalid or points outside its game root.",nameof(profile));
    var list=LoadForMutation().Where(x=>!x.Id.Equals(profile.Id,StringComparison.OrdinalIgnoreCase)).Append(profile).OrderBy(x=>x.DisplayName,StringComparer.OrdinalIgnoreCase).ToArray();
    Directory.CreateDirectory(stateRoot);AtomicWrite(registryPath,JsonSerializer.SerializeToUtf8Bytes(list,JsonOptions));
}
